  schema_version text NOT NULL,
  timeline jsonb NOT NULL,
  content_sha256 char(64) NOT NULL,
  created_by_type text NOT NULL,
  created_by_id text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, version)
);

CREATE TABLE render_jobs (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  timeline_version_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('PROXY','FINAL')),
  state text NOT NULL CHECK (state IN ('QUEUED', 'WAITING_RESOURCES', 'RUNNING', 'SEGMENT_DONE', 'CONCATENATING', 'QC_CHECK', 'SUCCEEDED', 'QC_FAILED', 'RETRYING', 'FAILED', 'CANCELLED')),
  preset jsonb NOT NULL,
  segments_total int NOT NULL DEFAULT 1,
  segments_done int NOT NULL DEFAULT 0,
  attempt int NOT NULL DEFAULT 0,
  output_asset_id uuid NULL,
  qc_report jsonb NULL,
  error_class text NULL,
  error_detail text NULL,
  started_at timestamptz NULL,
  finished_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  idempotency_key text UNIQUE NOT NULL
);
CREATE TRIGGER render_jobs_updated_at BEFORE UPDATE ON render_jobs FOR EACH ROW EXECUTE FUNCTION tf_set_updated_at();

CREATE TABLE thumbnails (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  asset_id uuid NOT NULL,
  aspect text NOT NULL CHECK (aspect IN ('16:9','9:16')),
  concept text NOT NULL,
  overlay_text text NULL,
  checks jsonb NOT NULL,
  passed_checks boolean NOT NULL,
  selected boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE seo_packages (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  version int NOT NULL,
  title_options jsonb NOT NULL,
  selected_title text NULL CHECK (char_length(selected_title) <= 100 AND selected_title !~ '[<>]'),
  description text NOT NULL CHECK (octet_length(description) <= 5000)
);

CREATE TABLE disclosure_assessments (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  recommended_value boolean NOT NULL,
  reasons jsonb NOT NULL,
  owner_confirmed_value boolean NULL,
  confirmed_by uuid NULL,
  confirmed_at timestamptz NULL,
  agent_run_id uuid NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE caption_tracks (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  language text NOT NULL,
  format text NOT NULL CHECK (format IN ('SRT','VTT')),
  asset_id uuid NOT NULL,
  method text NOT NULL CHECK (method IN ('SCRIPT_ALIGNED','TRANSCRIBED','OWNER_EDITED')),
  owner_reviewed boolean NOT NULL DEFAULT false,
  sync_check jsonb NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, language)
);

CREATE TABLE external_editors (
  code text PRIMARY KEY,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('DESKTOP','WEB','MOBILE')),
  supports_video boolean NOT NULL,
  supports_thumbnail boolean NOT NULL,
  launch_type text NOT NULL CHECK (launch_type IN ('EXE','URL','MANUAL')),
  exe_path text NULL,
  url text NULL,
  enabled boolean NOT NULL DEFAULT false,
  licence_notes text NULL,
  watermark_on_free_plan boolean NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER external_editors_updated_at BEFORE UPDATE ON external_editors FOR EACH ROW EXECUTE FUNCTION tf_set_updated_at();

CREATE TABLE external_edit_sessions (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  subject text NOT NULL CHECK (subject IN ('VIDEO','THUMBNAIL')),
  editor_code text NOT NULL,
  handoff_path text NOT NULL,
  source_asset_ids uuid[] NOT NULL,
  state text NOT NULL CHECK (state IN ('HANDED_OFF','RETURNED','CANCELLED')),
  returned_asset_id uuid NULL,
  declaration jsonb NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  returned_at timestamptz NULL
);

CREATE TABLE audit_reports (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  audit_type text NOT NULL CHECK (audit_type IN ('CONTENT','COPYRIGHT','POLICY','QUALITY','THUMBNAIL')),
  subject_sha256 char(64) NOT NULL,
  result text NOT NULL CHECK (result IN ('PASSED','WARNING','FAILED')),
  critical boolean NOT NULL DEFAULT false,
  score numeric(5,2) NOT NULL,
  findings jsonb NOT NULL,
  auditor_agent text NOT NULL,
  agent_run_id uuid NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE audit_overrides (
  id uuid PRIMARY KEY,
  audit_report_id uuid NOT NULL,
  overridden_by uuid NOT NULL,
  reason text NOT NULL CHECK (char_length(reason) >= 20),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER audit_overrides_append_only BEFORE UPDATE OR DELETE ON audit_overrides FOR EACH ROW EXECUTE FUNCTION tf_append_only();

CREATE TABLE approval_requests (
  id uuid PRIMARY KEY,
  channel_id uuid NULL,
  subject_type text NOT NULL,
  subject_id uuid NOT NULL,
  subject_sha256 char(64) NOT NULL,
  state text NOT NULL CHECK (state IN ('PENDING', 'APPROVED', 'CHANGES_REQUESTED', 'REJECTED', 'EXPIRED', 'INVALIDATED')),
  requested_by_type text NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now(),
  decided_by uuid NULL,
  decided_at timestamptz NULL,
  auto_rule_id text NULL,
  comment text NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  expires_at timestamptz NOT NULL
);

CREATE TABLE upload_jobs (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  channel_id uuid NOT NULL,
  approval_request_id uuid NOT NULL,
  file_asset_id uuid NOT NULL,
  file_sha256 char(64) NOT NULL,
  state text NOT NULL CHECK (state IN ('PREFLIGHT', 'REJECTED', 'WAITING_QUOTA', 'SESSION_STARTED', 'TRANSFERRING', 'RESUMING', 'UPLOADED', 'SETTING_THUMBNAIL', 'SETTING_CAPTIONS', 'SETTING_PLAYLIST', 'POLLING_PROCESSING', 'COMPLETED', 'PROCESSING_FAILED', 'FAILED')),
  privacy_status text NOT NULL CHECK (privacy_status IN ('private','unlisted','public')),
  publish_at timestamptz NULL CHECK (publish_at IS NULL OR privacy_status = 'private'),
  made_for_kids boolean NOT NULL,
  contains_synthetic_media boolean NOT NULL,
  session_started_at timestamptz NULL,
  session_uri_enc bytea NULL,
  key_id text NULL,
  bytes_total bigint NOT NULL,
  bytes_confirmed bigint NOT NULL DEFAULT 0,
  youtube_video_id text NULL,
  processing_status text NULL,
  steps jsonb NOT NULL DEFAULT '{}',
  attempt int NOT NULL DEFAULT 0,
  error_class text NULL,
  error_detail text NULL,
  is_test boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER upload_jobs_updated_at BEFORE UPDATE ON upload_jobs FOR EACH ROW EXECUTE FUNCTION tf_set_updated_at();

CREATE TABLE quota_ledger (
  id bigserial PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  pt_day date NOT NULL,
  gcp_project text NOT NULL,
  bucket text NOT NULL CHECK (bucket IN ('VIDEO_UPLOADS','SEARCH','DEFAULT','ANALYTICS')),
  method text NOT NULL,
  units int NOT NULL,
  reservation_id uuid NULL,
  channel_id uuid NULL,
  job_id text NULL,
  http_status int NULL,
  error_reason text NULL
);
CREATE TRIGGER quota_ledger_append_only BEFORE UPDATE OR DELETE ON quota_ledger FOR EACH ROW EXECUTE FUNCTION tf_append_only();

CREATE TABLE quota_reservations (
  id uuid PRIMARY KEY,
  gcp_project text NOT NULL,
  pt_day date NOT NULL,
  bucket text NOT NULL,
  units int NOT NULL,
  purpose text NOT NULL,
  job_id text NULL,
  state text NOT NULL CHECK (state IN ('HELD','SETTLED','RELEASED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);

CREATE TABLE quota_config (
  gcp_project text NOT NULL,
  bucket text NOT NULL,
  daily_limit int NOT NULL,
  reserve_pct int NOT NULL DEFAULT 10,
  research_share_pct int NOT NULL DEFAULT 30,
  method_costs jsonb NOT NULL,
  verified_at date NOT NULL,
  source_url text NOT NULL,
  PRIMARY KEY (gcp_project, bucket)
);

CREATE TABLE analytics_snapshots (
  id uuid PRIMARY KEY,
  channel_id uuid NOT NULL,
  youtube_video_id text NULL,
  snapshot_date date NOT NULL,
  metrics jsonb NOT NULL,
  fetched_at timestamptz NOT NULL,
  UNIQUE (channel_id, youtube_video_id, snapshot_date)
);

CREATE TABLE growth_suggestions (
  id uuid PRIMARY KEY,
  channel_id uuid NOT NULL,
  project_id uuid NULL,
  kind text NOT NULL,
  suggestion text NOT NULL,
  evidence jsonb NOT NULL,
  state text NOT NULL DEFAULT 'NEW' CHECK (state IN ('NEW','ACCEPTED','REJECTED','APPLIED')),
  decided_by uuid NULL,
  decided_at timestamptz NULL,
  agent_run_id uuid NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE comment_suggestions (
  id uuid PRIMARY KEY,
  channel_id uuid NOT NULL,
  youtube_comment_id text NOT NULL,
  comment_snapshot jsonb NOT NULL,
  fetched_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  suggestion_kind text NOT NULL CHECK (suggestion_kind IN ('REPLY','HOLD_FOR_REVIEW','MARK_SPAM','NONE')),
  suggested_reply text NULL,
  state text NOT NULL DEFAULT 'NEW' CHECK (state IN ('NEW','APPROVED','REJECTED','EXECUTED')),
  decided_by uuid NULL,
  decided_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (channel_id, youtube_comment_id)
);

CREATE TABLE data_deletion_tasks (
  id uuid PRIMARY KEY,
  channel_id uuid NULL,
  reason text NOT NULL CHECK (reason IN ('DISCONNECT','OWNER_REQUEST','RETENTION','REVOCATION_DETECTED')),
  scope jsonb NOT NULL,
  due_at timestamptz NOT NULL,
  completed_at timestamptz NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE agent_configurations (
  agent_code text PRIMARY KEY,
  name text NOT NULL,
  version text NOT NULL,
  is_auditor boolean NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  prompt_version text NOT NULL,
  provider_chain jsonb NOT NULL,
  limits jsonb NOT NULL,
  permissions jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NULL
);
CREATE TRIGGER agent_configurations_updated_at BEFORE UPDATE ON agent_configurations FOR EACH ROW EXECUTE FUNCTION tf_set_updated_at();

CREATE TABLE agent_runs (
  id uuid PRIMARY KEY,
  agent_code text NOT NULL,
  channel_id uuid NULL,
  project_id uuid NULL,
  job_id text NULL,
  input_sha256 char(64) NOT NULL,
  input jsonb NOT NULL,
  output jsonb NULL,
  status text NOT NULL CHECK (status IN ('RUNNING','SUCCEEDED','FAILED','REPAIRED','ABORTED','WAITING_QUOTA')),
  provider_code text NULL,
  model text NULL,
  tokens_in int NULL,
  tokens_out int NULL,
  duration_ms int NULL,
  repair_attempted boolean NOT NULL DEFAULT false,
  error_class text NULL,
  error_detail text NULL,
  quality_score numeric(5,2) NULL,
  started_at timestamptz NOT NULL,
  finished_at timestamptz NULL
);

CREATE TABLE workflow_transitions (
  id bigserial PRIMARY KEY,
  entity_type text NOT NULL,
  entity_id uuid NOT NULL,
  channel_id uuid NULL,
  from_state text NOT NULL,
  to_state text NOT NULL,
  event text NOT NULL,
  actor_type text NOT NULL,
  actor_id text NOT NULL,
  reason text NULL,
  idempotency_key text NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (entity_id, idempotency_key)
);
CREATE TRIGGER workflow_transitions_append_only BEFORE UPDATE OR DELETE ON workflow_transitions FOR EACH ROW EXECUTE FUNCTION tf_append_only();

CREATE TABLE job_meta (
  procrastinate_job_id bigint PRIMARY KEY,
  kind text NOT NULL,
  entity_id uuid NULL,
  idempotency_key text UNIQUE NOT NULL,
  ram_required_mb int NOT NULL DEFAULT 200,
  wait_state text NULL CHECK (wait_state IN ('WAITING_RESOURCES','WAITING_QUOTA')),
  wait_until timestamptz NULL,
  checkpoint jsonb NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE provider_registry (
  code text PRIMARY KEY,
  capability text NOT NULL CHECK (capability IN ('LLM','TTS','VOICE_CLONE','STT','IMAGE','VIDEO_GEN','STOCK','NOTIFY','RESEARCH')),
  tier text NOT NULL CHECK (tier IN ('L','F','P')),
  enabled boolean NOT NULL DEFAULT false,
  paid_activation_step int NOT NULL DEFAULT 0 CHECK (paid_activation_step BETWEEN 0 AND 2),
  licence text NOT NULL,
  licence_url text NULL,
  lineage text NULL,
  commercial_use text NOT NULL CHECK (commercial_use IN ('YES','NO','WITH_ATTRIBUTION','REVIEW')),
  data_use_training boolean NULL,
  languages text[] NOT NULL DEFAULT '{}',
  limits jsonb NOT NULL DEFAULT '{}',
  model_sha256 char(64) NULL,
  verified_at date NOT NULL,
  verified_url text NOT NULL,
  notes text NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER provider_registry_updated_at BEFORE UPDATE ON provider_registry FOR EACH ROW EXECUTE FUNCTION tf_set_updated_at();

CREATE TABLE provider_credentials (

);

CREATE TABLE usage_limits (
  id uuid PRIMARY KEY,
  provider_code text NOT NULL,
  scope text NOT NULL CHECK (scope IN ('GLOBAL','TASK','CHANNEL')),
  scope_ref text NULL,
  metric text NOT NULL CHECK (metric IN ('REQUESTS','TOKENS','CHARS','SECONDS','IMAGES','MONEY_MINOR')),
  period text NOT NULL CHECK (period IN ('MINUTE','DAY','MONTH')),
  limit_value bigint NOT NULL,
  reset_tz text NOT NULL DEFAULT 'America/Los_Angeles',
  UNIQUE (provider_code, scope, scope_ref, metric, period)
);

CREATE TABLE usage_records (
  id bigserial PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  provider_code text NOT NULL,
  period_key text NOT NULL,
  metric text NOT NULL,
  amount bigint NOT NULL,
  kind text NOT NULL CHECK (kind IN ('RESERVE','SETTLE','RELEASE')),
  agent_run_id uuid NULL,
  channel_id uuid NULL,
  task text NULL
);
CREATE TRIGGER usage_records_append_only BEFORE UPDATE OR DELETE ON usage_records FOR EACH ROW EXECUTE FUNCTION tf_append_only();

CREATE TABLE gateway_cache (
  cache_key char(64) PRIMARY KEY,
  provider_code text NOT NULL,
  response jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  hits int NOT NULL DEFAULT 0
);

CREATE TABLE cost_budgets (
  id uuid PRIMARY KEY,
  scope text NOT NULL CHECK (scope IN ('STOCK','PAID_PROVIDER')),
  provider_code text NULL,
  month char(7) NOT NULL,
  cap_minor bigint NOT NULL DEFAULT 0,
  spent_minor bigint NOT NULL DEFAULT 0,
  currency char(3) NOT NULL DEFAULT 'USD',
  CHECK (spent_minor <= cap_minor),
  UNIQUE (scope, provider_code, month)
);

CREATE TABLE notification_preferences (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL,
  event_type text NOT NULL,
  channel text NOT NULL CHECK (channel IN ('IN_APP','TELEGRAM','EMAIL','WHATSAPP')),
  enabled boolean NOT NULL,
  digest text NOT NULL DEFAULT 'NONE' CHECK (digest IN ('NONE','DAILY','WEEKLY')),
  UNIQUE (user_id, event_type, channel)
);

CREATE TABLE notification_targets (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL,
  channel text NOT NULL,
  target_enc bytea NOT NULL,
  key_id text NOT NULL,
  verified_at timestamptz NULL,
  UNIQUE (user_id, channel)
);

CREATE TABLE notifications (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL,
  channel_id uuid NULL,
  event_type text NOT NULL,
  severity text NOT NULL CHECK (severity IN ('INFO','WARNING','CRITICAL')),
  title text NOT NULL,
  body text NOT NULL,
  link text NULL,
  entity_type text NULL,
  entity_id uuid NULL,
  dedup_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz NULL
);

CREATE TABLE notification_deliveries (
  id uuid PRIMARY KEY,
  notification_id uuid NOT NULL,
  channel text NOT NULL CHECK (channel IN ('CREATED', 'SUPPRESSED', 'DEFERRED', 'DIGEST_PENDING', 'QUEUED', 'SENT', 'RETRYING', 'FAILED', 'READ')),
  state text NOT NULL,
  attempts int NOT NULL DEFAULT 0,
  next_attempt_at timestamptz NULL,
  provider_message_id text NULL,
  last_error text NULL,
  sent_at timestamptz NULL,
  UNIQUE (notification_id, channel)
);

CREATE TABLE system_health_samples (
  id bigserial PRIMARY KEY,
  sampled_at timestamptz NOT NULL DEFAULT now(),
  ram_free_mb int,
  disk_free_gb numeric(8,2),
  cpu_pct numeric(5,2),
  queue_depth jsonb,
  failed_jobs_24h int
);

CREATE TABLE backups (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('DB','SECRETS','MEDIA')),
  path text NOT NULL,
  size_bytes bigint,
  sha256 char(64),
  started_at timestamptz,
  finished_at timestamptz,
  status text NOT NULL,
  error text NULL,
  restore_tested_at timestamptz NULL
);

CREATE TABLE provider_reverify_reminders (
  provider_code text PRIMARY KEY,
  due_at date NOT NULL
);

CREATE TABLE adr_references (
  adr_id text PRIMARY KEY,
  title text NOT NULL,
  status text NOT NULL,
  path text NOT NULL
);

CREATE TABLE idempotency_keys (
  user_id uuid NOT NULL,
  key uuid NOT NULL,
  method text NOT NULL,
  path text NOT NULL,
  request_sha256 char(64) NOT NULL,
  status_code int NULL,
  response_body jsonb NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (user_id, key)
);

CREATE UNIQUE INDEX user_roles_unique ON user_roles (user_id, role_id, COALESCE(channel_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE INDEX ON sessions (user_id) WHERE revoked_at IS NULL;
CREATE INDEX ON user_recovery_codes (user_id) WHERE used_at IS NULL;
CREATE INDEX ON audit_log (entity_type, entity_id, occurred_at DESC);
CREATE INDEX ON audit_log (channel_id, occurred_at DESC);
CREATE INDEX ON audit_log (actor_type, actor_id, occurred_at DESC);
CREATE UNIQUE INDEX ON oauth_connections (channel_id) WHERE status <> 'REVOKED';
CREATE INDEX ON trend_items (channel_id, status, expires_at);
CREATE INDEX ON youtube_api_cache (expires_at);
CREATE INDEX ON video_ideas (channel_id, state);
CREATE INDEX ON video_projects (channel_id, state);
CREATE INDEX ON fact_check_claims (subject_type, subject_id, verdict);
CREATE INDEX ON media_assets (sha256);
CREATE INDEX ON media_assets (project_id, kind);
CREATE UNIQUE INDEX ON narration_segments (scene_id) WHERE selected;
CREATE UNIQUE INDEX ON thumbnails (project_id) WHERE selected;
CREATE INDEX ON external_edit_sessions (project_id, state);
CREATE INDEX ON audit_reports (project_id, audit_type, created_at DESC);
CREATE INDEX ON approval_requests (state, requested_at) WHERE state = 'PENDING';
CREATE UNIQUE INDEX upload_once ON upload_jobs (project_id, file_sha256) WHERE state NOT IN ('FAILED','REJECTED');
CREATE INDEX ON quota_ledger (gcp_project, pt_day, bucket);
CREATE INDEX ON agent_runs (agent_code, started_at DESC);
CREATE INDEX ON agent_runs (project_id);
CREATE INDEX ON workflow_transitions (entity_type, entity_id, occurred_at);
CREATE INDEX ON usage_records (provider_code, period_key, metric);
CREATE INDEX ON notifications (user_id, read_at, created_at DESC);
CREATE INDEX ON notifications (dedup_key, created_at DESC);
CREATE INDEX ON idempotency_keys (expires_at);

